fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through the elements of both vectors
    for i in 0..a.len() {
        // Perform the XOR operation and push the result to the new vector
        result.push(a[i] ^ b[i]);
    }
    
    result
}